{
  "items": [
    {
      "name": "MvPolynomial.toMvPowerSeries",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [inst : CommSemiring R] → MvPolynomial σ R → MvPowerSeries σ R"
    },
    {
      "name": "MvPolynomial.coeff_X_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (m : σ →₀ ℕ) (s : σ) (p : MvPolynomial σ R),\n  MvPolynomial.coeff (Finsupp.single s 1 + m) (MvPolynomial.X s * p) = MvPolynomial.coeff m p"
    },
    {
      "name": "MvPolynomial.coeffs",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset R"
    },
    {
      "name": "MvPolynomial.coeffs_X_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R) (n : σ),\n  (MvPolynomial.X n * p).coeffs = p.coeffs"
    },
    {
      "name": "MvPolynomial.coe_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] (n : σ →₀ ℕ) (a : R),\n  ↑((MvPolynomial.monomial n) a) = (MvPowerSeries.monomial n) a"
    },
    {
      "name": "MvPolynomial.coeff_mul_X",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (m : σ →₀ ℕ) (s : σ) (p : MvPolynomial σ R),\n  MvPolynomial.coeff (m + Finsupp.single s 1) (p * MvPolynomial.X s) = MvPolynomial.coeff m p"
    },
    {
      "name": "MvPolynomial.coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPolynomial σ R → R"
    },
    {
      "name": "MvPolynomial.coeToMvPowerSeries",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "instance",
      "type": "{σ : Type u_1} → {R : Type u_2} → [inst : CommSemiring R] → Coe (MvPolynomial σ R) (MvPowerSeries σ R)"
    }
  ]
}
